from solution import check_if_last_char_is_a_letter
import string

import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


# Obviously-correct reference model derived from spec:
# True iff last char is an English alphabetical character (A-Z/a-z)
# and it forms a single-character token, i.e. string is exactly
# that char or the char before it is a space.
# Anything ending with space is False. Empty is False.
def ref(txt: str) -> bool:
    if len(txt) == 0:
        return False
    last = txt[-1]
    if last not in string.ascii_letters:
        return False
    if len(txt) == 1:
        return True
    if txt[-2] == " ":
        return True
    return False


# ---- explicit spec examples ----
def test_example_apple_pie_is_false():
    assert check_if_last_char_is_a_letter("apple pie") is False


def test_example_apple_pi_e_is_true():
    assert check_if_last_char_is_a_letter("apple pi e") is True


def test_example_trailing_space_is_false():
    assert check_if_last_char_is_a_letter("apple pi e ") is False


def test_example_empty_is_false():
    assert check_if_last_char_is_a_letter("") is False


# ---- single / isolated letters ----
def test_property_single_ascii_letter_is_true():
    for c in string.ascii_letters:
        assert check_if_last_char_is_a_letter(c) is True


@given(st.text(alphabet=st.characters(blacklist_categories=("Cs",)), max_size=20))
def test_property_equivalence_to_ascii_reference_model(txt):
    assert check_if_last_char_is_a_letter(txt) == ref(txt)


@given(st.text(alphabet=st.sampled_from(string.ascii_letters + " "), min_size=0, max_size=20))
def test_property_equivalence_restricted_alphabet(txt):
    assert check_if_last_char_is_a_letter(txt) == ref(txt)


def test_property_isolated_ascii_letters_are_true():
    # "<arbitrary prefix without trailing space> + ' ' + letter" must be True
    prefixes = ["", "a", "apple", "apple pie", " ", "  ", "a b", "1", "1 2"]
    for pre in prefixes:
        for c in ["a", "Z", "e", "Q"]:
            txt = pre + " " + c if pre != "" else c
            # build explicitly: ensure last two chars are " X"
            if len(txt) >= 2 and txt[-2] == " " and txt[-1] in string.ascii_letters:
                assert check_if_last_char_is_a_letter(txt) is True, txt


def test_property_trailing_space_always_false():
    for base in ["", "a", "e", "apple pi e", "x", " "]:
        assert check_if_last_char_is_a_letter(base + " ") is False
        assert check_if_last_char_is_a_letter(base + "  ") is False


@given(st.text(alphabet=st.characters(blacklist_categories=("Cs",)), max_size=20))
def test_property_appending_space_forces_false(txt):
    assert check_if_last_char_is_a_letter(txt + " ") is False


def test_property_last_word_longer_than_one_is_false():
    # last token (split by ' ') has length > 1 -> False regardless of alpha
    cases = ["apple pie", "apple pi eee", "ab", "a bc", "a bcd", "hi", "x yy", "e fgh"]
    for txt in cases:
        assert check_if_last_char_is_a_letter(txt) is False, txt


@given(st.text(alphabet=st.sampled_from(string.ascii_letters), min_size=2, max_size=10))
def test_property_multi_letter_word_without_spaces_is_false(word):
    assert check_if_last_char_is_a_letter(word) is False


def test_property_non_alpha_last_char_is_false():
    # digits, punctuation, underscore isolated by space must still be False
    for c in ["0", "9", "!", "?", ".", ",", "_", "-", ":", ";", "0", "@", "#", "(", ")"]:
        assert check_if_last_char_is_a_letter(c) is False, c
        assert check_if_last_char_is_a_letter("apple " + c) is False, c
        assert check_if_last_char_is_a_letter("a " + c) is False, c


@given(st.sampled_from(list("0123456789_!@#$%^&*()-+=.,;:?/")))
def test_property_any_non_letter_single_char_is_false(c):
    assert check_if_last_char_is_a_letter(c) is False


@given(st.text(alphabet=st.sampled_from(string.ascii_letters + " "), min_size=1, max_size=20))
def test_property_appending_letter_to_true_makes_false(txt):
    # metamorphic: if txt ends with isolated letter (True), extending that
    # token by one more letter must make it False
    assume(ref(txt) is True)
    extra = st.sampled_from(list(string.ascii_letters)).example() if False else "x"
    assert check_if_last_char_is_a_letter(txt + extra) is False


def test_property_extending_isolated_letter_makes_false():
    assert check_if_last_char_is_a_letter("apple pi e") is True
    assert check_if_last_char_is_a_letter("apple pi ex") is False
    assert check_if_last_char_is_a_letter("a") is True
    assert check_if_last_char_is_a_letter("ax") is False
    assert check_if_last_char_is_a_letter("a b") is True
    assert check_if_last_char_is_a_letter("a bc") is False


def test_property_preceded_by_non_space_is_false():
    # last char is ascii letter but previous char is not space -> False
    cases = ["ab", "a1b", "a-b", "a_b", "a\tb", "a\nb", "1a", ".a", "aa"]
    for txt in cases:
        assert check_if_last_char_is_a_letter(txt) is False, txt


def test_property_unicode_alpha_isolated_is_false():
    # English alphabet only: non-ASCII alphabetic chars are not "alphabetical"
    # per spec examples (a-z). isalpha() over-accepts them.
    for c in ["é", "ñ", "ü", "α", "β", "я", "中", "ß"]:
        assert check_if_last_char_is_a_letter(c) is False, repr(c)
        assert check_if_last_char_is_a_letter("apple " + c) is False, repr(c)
        assert check_if_last_char_is_a_letter("a " + c) is False, repr(c)


def test_property_empty_and_spaces_only_are_false():
    assert check_if_last_char_is_a_letter("") is False
    assert check_if_last_char_is_a_letter(" ") is False
    assert check_if_last_char_is_a_letter("  ") is False
    assert check_if_last_char_is_a_letter("   ") is False


@given(st.integers(min_value=1, max_value=10))
def test_property_spaces_only_are_false(n):
    assert check_if_last_char_is_a_letter(" " * n) is False


def test_property_double_space_before_letter_is_true():
    # separator is space, so multiple spaces still isolate last char
    assert check_if_last_char_is_a_letter("a  b") is True
    assert check_if_last_char_is_a_letter("a  e") is True
    assert check_if_last_char_is_a_letter("  e") is True
    assert check_if_last_char_is_a_letter("apple  e") is True
